%[text] ## List of relevant scans
%[text] For each working distance a whole series of scans were taken to measure the beamwidth. Two points on the sample were used, all of the scans are associated with one of these.
%[text] The regions are the yellow rectangles in this image:
%[text] ![line_scans.png](text:image:6136)
% All scans
addpath('2021_04_Source_further_350nm')
scans=[003034 003049 003056 003059 003062 003064 003067 003069 003072 003075 ...
    003077 003079 003081 003083 003085 003087 003091 003093 003095 003097 003112 ...
    003114 003116];

% Croped range of the scans used for the fitting
xrange=[545 740; 800 1000; 1100 1400; 820 1350; 800 1400; 1130 1600;...
    1130 1550; 700 1250; 1100 1550; 400 850; 900 1500; 600 1200; 600 1300; ...
    400 800; 650 1050; 750 1150; 500 850; 650 1000; 500 900; 840 1200; 350 750;...
    200 600; 1000 1500];

% Associating scans with the two points on the sample
scans_p1=[3 4 7 8 11 12 15 16 19 20 23]; %excluded 1
scans_p2=[2 5 6 9 10 13 14 17 18 21 22];

%%
%[text] ## Running the fit (recommended to turn off output of all fit plots)
%[text] An error function 
%[text] $I(x) = a\\,\\mathrm{Erf}\\left(\\frac{x - \\mu}{\\sigma}\\right) + c$
%[text] with $\\sigma$ as the beam standard deviation, is fitted to each horizontal line, with the average of all lines in each dataset used as the width. The uncertainty in the beamwidth is calculated from the spread in the fitted values of $\\sigma$. The average taken between all the data points is a weighted average
%[text] $\\bar{X} = \\frac{\\sum\_i X\_i/\\sigma\_i^2}{\\sum\_i 1/\\sigma\_i^2}$
%[text] with the resulting errors being
%[text] $\\bar{\\sigma} = \\frac{1}{\\sum\_i \\frac{1}{\\sigma\_i^2}$
%RECCOMENDED: output of all fits can be
%supressed by setting last input to 0 as matlab doesn't like making so many figures,
% titles seem to also be kind of messed up.
for ind=1:length(scans) %[output:group:0284d5c2]
    %disp(['on ' num2str(ind) ' scan of ' ])
    [~,~,FWHM_data(ind,1),FWHM_data(ind,2),FWHM_data(ind,3),FWHM_data(ind, 4)]=beamFWHM(scans(ind), ... %[output:52921ccb] %[output:87a271b2] %[output:8332416d] %[output:2f0249d6] %[output:211e2a03] %[output:147cb208] %[output:2fb50bb8] %[output:38fe3ea5] %[output:11a85fe1] %[output:2471c37d] %[output:2805471c] %[output:5c8c89b1] %[output:50ff543a] %[output:317e3b60] %[output:02f5dffe] %[output:0362f016] %[output:0c87c18d] %[output:3e3e085d] %[output:12f8d90e] %[output:593e7dc8] %[output:504fb5ca] %[output:551570d1] %[output:83228de4] %[output:379f7f6f] %[output:89f81fd7] %[output:829e95a8] %[output:72d6c867] %[output:57f52112] %[output:2e5ed176] %[output:4c5e90c1] %[output:3b87283d] %[output:770825c2] %[output:11685e4b] %[output:5863fb32] %[output:9996ffd9] %[output:4e2db34f] %[output:88eab2e2] %[output:02ba8cdb] %[output:5b8f2109] %[output:4de56230] %[output:840d683e] %[output:981a79f5] %[output:24b89576] %[output:17d8c2c9] %[output:61ef2f35] %[output:73b898ea]
        'hori', 3770, xrange(ind,1), xrange(ind,2), false);  %[output:52921ccb] %[output:87a271b2] %[output:8332416d] %[output:2f0249d6] %[output:211e2a03] %[output:147cb208] %[output:2fb50bb8] %[output:38fe3ea5] %[output:11a85fe1] %[output:2471c37d] %[output:2805471c] %[output:5c8c89b1] %[output:50ff543a] %[output:317e3b60] %[output:02f5dffe] %[output:0362f016] %[output:0c87c18d] %[output:3e3e085d] %[output:12f8d90e] %[output:593e7dc8] %[output:504fb5ca] %[output:551570d1] %[output:83228de4] %[output:379f7f6f] %[output:89f81fd7] %[output:829e95a8] %[output:72d6c867] %[output:57f52112] %[output:2e5ed176] %[output:4c5e90c1] %[output:3b87283d] %[output:770825c2] %[output:11685e4b] %[output:5863fb32] %[output:9996ffd9] %[output:4e2db34f] %[output:88eab2e2] %[output:02ba8cdb] %[output:5b8f2109] %[output:4de56230] %[output:840d683e] %[output:981a79f5] %[output:24b89576] %[output:17d8c2c9] %[output:61ef2f35] %[output:73b898ea]
end %[output:group:0284d5c2]
% Z WD converted to beam line WD due to 45deg incidence angle
WDs = 300:0.1:1000*sqrt(2);
% Error on the working distance
pos_error = ones(length(scans))*25;
%%
%[text] ### Plots of widths
%[text] Plot the extracted widths and export data to a text file (final figure is made in python.
Point1 = table([FWHM_data(scans_p1(1), 3)], [FWHM_data(scans_p1(1), 1)], [FWHM_data(scans_p1(1), 2)], [FWHM_data(scans_p1(1), 4)], VariableNames={'WD', 'FWHM', 'sig', 'SNR'});

figure %point1 plot wiwth errors %[output:73f2b16b]
hold on %[output:73f2b16b]
i_ = 1;
for ind=scans_p1
    errorbar(FWHM_data(ind,3), FWHM_data(ind,1), FWHM_data(ind,2), ... %[output:73f2b16b]
        FWHM_data(ind,2), pos_error(ind), pos_error(ind) , 'kx') %[output:73f2b16b]
    Point1 = [Point1; {FWHM_data(ind,3), FWHM_data(ind, 1), FWHM_data(ind, 2), FWHM_data(ind, 4)}];
end
hold off %[output:73f2b16b]

xlabel 'Beam-line working distance/\mum' %[output:73f2b16b]
ylabel 'Beam FWHM/nm' %[output:73f2b16b]
title 'Point 1' %[output:73f2b16b]
Point2 = table([[FWHM_data(scans_p2(1), 3)]], [FWHM_data(scans_p2(1), 1)], [FWHM_data(scans_p2(1), 2)], [FWHM_data(scans_p2(1), 4)], VariableNames={'WD', 'FWHM', 'sig', 'SNR'});

figure %point2 plot with errors %[output:6625fd0f]
hold on %[output:6625fd0f]
for ind=scans_p2
    
    errorbar(FWHM_data(ind,3), FWHM_data(ind,1), FWHM_data(ind,2), ... %[output:6625fd0f]
        FWHM_data(ind,2), pos_error(ind), pos_error(ind) , 'kx') %[output:6625fd0f]
    Point2 = [Point2; {FWHM_data(ind,3), FWHM_data(ind, 1), FWHM_data(ind, 2), FWHM_data(ind, 4)}];
end
hold off %[output:6625fd0f]
xlabel 'Beam-line working distance/\mum' %[output:6625fd0f]
ylabel 'Beam FWHM/nm' %[output:6625fd0f]
title 'Point 2' %[output:6625fd0f]
% Need to drop the first row of the tables because of the wierd way I've
% made them
Point1([1], :) = [];
Point2([1], :) = [];

% Save to a text file
writetable(Point1, 'point1.csv')
writetable(Point2, 'point2.csv')
