%[text] ## Functions for self contained script
%[text] These functions fit an error function to the data to extract the beamwidth.
%[text] $I(x) = a\\,  \\mathrm{erf}\\left(\\frac{x-\\mu}{\\sigma}\\right) + c$
%[text] Where a is the amplitude of the change in intensity, mu is the position of the dip, sigma is the beam standard deviation adn c is the offset.
%[text] Additionally to the beamwidth (as extracted in sigma), we can also make a basic estimation of the signal to noise through the amplitude a and the residuals.
% Fits an error function to a line scan over an edge, returns the standard
% deviation, the centre and the fit standard errors for both of those 
% quantaties calculated with `confit`.
function [sig, sig_error, pos, pos_error, SNR] = fit_single_width(positions, signals, plot_)
    x = positions;
    y = signals/mean(signals);

    %disp('starting fit')
    
    % Fit: 'untitled fit 1'.
    [xData, yData] = prepareCurveData(x, y);
    
    % Set up fittype and options.
    ft = fittype( 'a*normcdf((x-u)/s)+c', 'independent', 'x', 'dependent', 'y' );
    opts = fitoptions( 'Method', 'NonlinearLeastSquares');
    opts.Display = 'Off';
    % Minus sign on first parameter because signal drops
    opts.StartPoint = [-0.1 1 1000 mean(x)];
    
    % Fit model to data.
    [fitresult, ~] = fit(xData, yData, ft, opts);
    errors = confint(fitresult, 0.682);
    
    sig = fitresult.s; % Beam standrad deviation
    pos = fitresult.u; % Position of the 
    sig_error = (errors(2,3)-errors(1,3))/2;
    pos_error = (errors(2,4)-errors(1,4))/2;
    
    % Calulate residuals 
    a = fitresult.a;
    c = fitresult.c;
    residuals = (a*normcdf((x-pos)/sig) + c) - y;
    % Estimate the SNR based on the magnitude of the error function and the
    % standard deviation of the residuals
    SNR = abs(a)/std(residuals);

    %disp(['finished fit, estimate SNR:' num2str(SNR) ', doing plot'])

    if plot_==1
        % Plot fit with data.
        figure('Units','normalized','Position',[0.2 0.2 0.6 0.5]);
           
        nexttile
        plot(fitresult, xData, yData);
        xlabel('x/nm')
        ylabel('I/arb.')
        grid on
        title(sprintf('s = %inm', round(sig, 2, 'significant')));

        nexttile
        plot(x, residuals, 'k.');
        yline(0)
        grid on
        xlabel('x/nm')
        ylabel('residual/arb.')
    end
    %disp('finished plot')
end

% Performs a series of fits on all of the rows in a set image. Averages the
% fit results and combines the errors.
function [sig,sig_err,FWHM_mean, FWHM_err_mean,WD, SNR_mean] = beamFWHM(scanxx, type, z_zero, xmin, xmax, plot_)
    
    fname = ['scan00', num2str(scanxx), '.mat'];
    load(fname, 'meas_list');
    meas = meas_list{1};
    dwell_time = meas.N_dwell*meas.sampling_period; % ms
    disp(string(meas.date_time))
    disp(['dwell time: ' num2str(dwell_time) 'ms'])
    ECCZ_zero = z_zero; % zero position of the sample stages
    ECCZ_actual = meas.initial_pos(3)/1000;
    WD = abs(ECCZ_actual-ECCZ_zero)*sqrt(2); % beam line WD hence factor of sqrt(2)
    
    switch lower(type)
        case 'vert'
            %data=meas.image(:,1)';
            data=meas.image';
            data=data(:,xmin:xmax);
            pos=meas.vert_range(2):meas.vert_res:meas.vert_range(1);
            pos=pos(xmin:xmax);
            figure
            imagesc(data)
            colormap gray
            
        case 'hori'
            %data=meas.image(1,:);
            data=meas.image;
            data=data(:,xmin:xmax);
            pos=meas.hori_range(2):meas.hori_res:meas.hori_range(1);
            pos=pos(xmin:xmax);
            figure
            imagesc([pos(1) pos(end)].*1e-4, [1 size(data,1)], data)
            colormap gray
        otherwise
            disp('wrong input')
    end
    drawnow
    
    sd2 = ones(size(data,1), 1)*nan;
    sd2_error = ones(size(data,1), 1)*nan;
    
    if plot_
        for ind=1:size(data,1)
            [sig(ind),sig_err(ind),~,~, SNR(ind)]=fit_single_width(pos, data(ind,:), plot_);
            title(['WD = ',num2str(WD), '\mum;     ', '\sigma = ', num2str(round(sig(ind))), 'nm']);
            hAx = gca;
            hAx.YAxis.TickLabelFormat=('%0.1f');
            hAx.XAxis.TickLabelFormat=('%d');
            hAx.XAxis.TickValues=[pos(1):7.5e2:pos(end)];
            %     data(1,end)
            %     data(1,1):0.2:data(1,end)
            %     hAx.YAxis.TickValues=[data(1,1):0.2:data(1,end)];
            hAx.XAxis.Exponent=3;
            xlabel('pos/nm');
            ylabel('He Signal');
        end
    else
        for ind=1:size(data,1)
            [sig(ind),sig_err(ind),~,~, SNR(ind)]=fit_single_width(pos, data(ind,:), plot_);        
        end
    end

    % Exclude fits that failed (1 fit is known to fail and result in a very
    % small FWHM for the smallest working distance dataset, plus one in the
    % 707um WD dataset)
    FWHM = sig*2*sqrt(2*log(2));
    Ind = FWHM > 150;
    FWHM = FWHM(Ind);
    sig_err = sig_err(Ind);

    % Average the SNR values to get a better picture of that
    % Also normalise the SNR for a 2s dwell time
    SNR_mean = mean(SNR)*sqrt(2000/dwell_time);

    % Error combination for the means of the multiple fits.
    FWHM_err = sig_err.*2*sqrt(2*log(2));
    FWHM_err_mean = sqrt(1./sum(1./FWHM_err.^2));    
    FWHM_mean = sum(FWHM./FWHM_err.^2)/sum(1./FWHM_err.^2);
    
    %title of line scan plots
    title({['WD = ',num2str(round(WD)), '\mum;     ', 'FWHM = ', num2str(round(FWHM)), 'nm']}, ...
        {['err = ', num2str(round(FWHM_err))]});
end

